#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}


# ──────────────────────────────────────────────────────────────────────────
# STAGES
# ──────────────────────────────────────────────────────────────────────────
#
# `deadlift server provision` runs this: it gets a new Server, walking the maintainer through each
# step only they can do, in a browser or a terminal, and doing the rest over SSH from their own
# computer. In order: the tailnet policy, buying the machine, the provider's firewall, bootstrap,
# joining the tailnet, and closing public SSH.
#
# Hetzner Cloud appears only in these instructions. Bootstrap needs nothing of it: any fresh
# Ubuntu 24.04 machine with a public IPv4 address and root SSH by key will do.
#
# The tailnet policy entries it prints (cli/tailscale-policy.hujson) are set once per tailnet, by
# tag, so a second Server on the same tailnet, and every App's Service, need nothing new there.
# It never reads or writes the policy: the maintainer, or the setup-deadlift skill, merges them.
#
# Safe to stop and run again: answers are kept in $ENV_FILE (below) and offered again, and each
# stage checks what's done. A run that finishes with nothing left to do by hand forgets them, so
# the next run provisions a new Server.

root=$(cd "$(dirname "$(readlink -f "${BASH_SOURCE[0]}")")/.." && pwd)

SERVER_TAG=tag:deadlift-server
SSH_OPTIONS=(-o StrictHostKeyChecking=accept-new -o ConnectTimeout=10)
# Answers kept in ENV_FILE that a later stage needs even when an earlier one is skipped.
SAVED_ANSWERS=(SERVER_NAME SERVER_IP TAILNET POLICY_SAVED FIREWALL_CREATED)

# Every ssh here passes the wizard's stdin through, so a command that reads nothing takes
# </dev/null, or it would swallow what the human types next.

# The Server's name on the tailnet.
server_host() {
  printf '%s.%s' "$SERVER_NAME" "$TAILNET"
}

# Whether root on the Server answers over the tailnet yet.
tailnet_ready() {
  [[ -n ${TAILNET:-} && -n ${SERVER_NAME:-} ]] &&
    ssh -o BatchMode=yes "${SSH_OPTIONS[@]}" "root@$(server_host)" true </dev/null >/dev/null 2>&1
}

# Whether root on the machine's public address still answers SSH.
public_ssh_answers() {
  ssh -o BatchMode=yes "${SSH_OPTIONS[@]}" "root@$SERVER_IP" true </dev/null >/dev/null 2>&1
}

# Whether this computer's tailnet already has a deadlift Server, whose policy entries every other
# Server shares. Reads this computer's own `tailscale`, if it has one signed in.
tailnet_has_server() {
  (tailscale status --json 2>/dev/null </dev/null || true) | grep -q "\"$SERVER_TAG\""
}

# Runs `deadlift server bootstrap` over whichever route answers: the tailnet once the Server has
# joined it, otherwise the public address.
run_bootstrap() {
  local host=$SERVER_IP
  if tailnet_ready; then host=$(server_host); fi
  "$root/bin/deadlift" server bootstrap "$host" </dev/null
}

# Runs "$@" until it succeeds or the human stops trying.
until_it_works() {
  until "$@"; do
    warn "that didn't work"
    confirm "Try again?" || return 1
  done
}

run_wizard() {

TOTAL_STAGES=6
ENV_FILE=${XDG_STATE_HOME:-$HOME/.local/state}/deadlift/provision.env
mkdir -p "$(dirname "$ENV_FILE")"
for key in "${SAVED_ANSWERS[@]}"; do
  printf -v "$key" '%s' "$(_existing "$key" || true)"
done

banner "Provision a deadlift Server"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Tailscale: the tailnet policy"
if [[ -n $POLICY_SAVED ]]; then
  note "You saved deadlift's entries in the tailnet policy in an earlier run, so there's nothing to add."
  pause "Continue?"
elif tailnet_has_server; then
  say "This tailnet already has a deadlift Server, so its policy already holds every entry a"
  say "Server needs. They're set once per tailnet, so there's nothing to add for this one."
  pause "Continue?"
  write_env POLICY_SAVED yes
else
  say "The policy decides who reaches a Server, before it exists. These entries are set once"
  say "per tailnet: every deadlift Server, and every App's Service, is covered by its tag."
  note "Servers are tagged $SERVER_TAG, and each App's Service tag:deadlift-svc. Servers serve"
  note "any App's Service without approval by hand, and everyone on the tailnet reaches every"
  note "App at 443 and its Slots' ports. Members SSH to Servers as root."
  open_url "https://login.tailscale.com/admin/acls/file"
  step "Merge each section below into the section of the same name, keeping what's there:"
  printf '\n'
  sed -e '/^\/\//d' -e 's/^/    /' "$root/cli/tailscale-policy.hujson"
  printf '\n'
  step "Save. (The same text is in cli/tailscale-policy.hujson.)"
  pause "Saved?"
  write_env POLICY_SAVED yes
fi

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Hetzner: buy the Server"
say "Any fresh Ubuntu 24.04 machine with a public IPv4 address and root SSH by key will do."
say "These steps buy one at Hetzner Cloud. Bought it already? Give its name and address."
note "Its name, at Hetzner and on the tailnet: a-z, 0-9 and -, such as deadlift-1."
while true; do
  ask SERVER_NAME "The Server's name:"
  [[ $SERVER_NAME =~ ^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?$ ]] && break
  warn "that isn't a name: a-z, 0-9 and -, not starting or ending with -"
done
write_env SERVER_NAME "$SERVER_NAME"
open_url "https://console.hetzner.cloud/"
step "Open your project, then Add Server (or Create Resource > Servers)"
step "Location: any. Image: Ubuntu 24.04"
step "Type: Shared vCPU, x86 (Intel/AMD). CX23 (2 vCPU, 4 GB RAM, 40 GB disk) fits a small"
note "  App or two; CX33 (4 vCPU, 8 GB, 80 GB) a few more"
step "Networking: public IPv4 on. SSH keys: tick this computer's, so root logs in by key"
note "  None there yet? Add Key with ~/.ssh/id_ed25519.pub (ssh-keygen -t ed25519 makes one)"
step "Name: $SERVER_NAME. Then Create & Buy now"
while true; do
  ask SERVER_IP "The Server's public IPv4 address:"
  [[ $SERVER_IP =~ ^[0-9]{1,3}(\.[0-9]{1,3}){3}$ ]] && break
  warn "that isn't an IPv4 address, like 203.0.113.7"
done
write_env SERVER_IP "$SERVER_IP"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Hetzner: the firewall"
say "Nothing on a Server faces the internet: the provider's firewall blocks every inbound"
say "connection. Tailscale needs none, as it connects out. SSH stays open for now, for"
say "bootstrap and joining the tailnet, and the last stage closes it."
if [[ -n $FIREWALL_CREATED ]]; then
  note "You created and applied it in an earlier run."
  pause "Continue?"
else
  open_url "https://console.hetzner.cloud/"
  step "In your project: Firewalls > Create Firewall. Name: $SERVER_NAME"
  step "Inbound: delete every rule but SSH (TCP, port 22)"
  step "Outbound: leave it empty, which allows everything"
  step "Apply to: the $SERVER_NAME server. Then Create Firewall"
  pause "Created and applied?"
  write_env FIREWALL_CREATED yes
fi

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Bootstrap the Server"
say "deadlift server bootstrap installs Docker with userns-remap, Tailscale, the firewall for"
say "containers, the entry command and the deploy script, from this checkout of deadlift."
say "It runs as root over SSH, and is safe to run again."
until_it_works run_bootstrap || exit 1
pause "Bootstrapped? Continue?"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Tailscale: join the tailnet"
if tailnet_ready; then
  note "root@$(server_host) already answers over the tailnet."
else
  say "The Server asks to join as $SERVER_NAME, tagged $SERVER_TAG, with Tailscale SSH on."
  step "Open the link it prints and sign in as an admin of the tailnet, who owns the tag."
  note "It returns once you have."
  # -t: a terminal, so the link shows as soon as it's printed.
  until_it_works ssh -t "${SSH_OPTIONS[@]}" "root@$SERVER_IP" \
    tailscale up --ssh --hostname="$SERVER_NAME" --advertise-tags="$SERVER_TAG" || exit 1
  # This computer's own tailnet, if its tailscale is signed in.
  guess=$( (tailscale status --json 2>/dev/null </dev/null || true) |
    sed -n 's/.*"MagicDNSSuffix": *"\([^"]*\)".*/\1/p' | head -n 1)
  open_url "https://login.tailscale.com/admin/dns"
  step "Copy the Tailnet DNS name, like tail1a2b3c.ts.net"
  if [[ -n $guess ]]; then note "This computer's tailnet is $guess: Enter takes it."; fi
  ask TAILNET "Your tailnet DNS name:" || true
  TAILNET=${TAILNET:-$guess}
  TAILNET=${TAILNET#.}
  write_env TAILNET "$TAILNET"
  until_it_works tailnet_ready || exit 1
fi
if ssh "${SSH_OPTIONS[@]}" "root@$(server_host)" tailscale status --json </dev/null 2>/dev/null |
  grep -q "\"$SERVER_TAG\""; then
  printf '  %s✓%s root@%s answers over Tailscale SSH, tagged %s\n' "$GREEN" "$RESET" "$(server_host)" "$SERVER_TAG"
else
  warn "$(server_host) answers, but isn't tagged $SERVER_TAG. Check it under Machines."
  SKIPPED+=("tagging $SERVER_NAME $SERVER_TAG: Machines > $SERVER_NAME > Edit ACL tags")
fi
pause "Continue?"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Hetzner: close public SSH"
say "Everything now goes over the tailnet, as root@$(server_host) with Tailscale SSH, so"
say "the public address needs no inbound connection at all."
if public_ssh_answers; then
  open_url "https://console.hetzner.cloud/"
  step "In your project: Firewalls > $SERVER_NAME > Rules"
  step "Inbound: delete the SSH rule, leaving none. Then Save"
  pause "Deleted?"
  while public_ssh_answers; do
    warn "SSH on $SERVER_IP still answers. Check the firewall has no inbound rule and is applied to $SERVER_NAME."
    if ! confirm "Check again?"; then
      SKIPPED+=("closing public SSH on $SERVER_IP: delete the firewall's SSH rule")
      break
    fi
  done
fi
if ! public_ssh_answers; then
  printf '  %s✓%s SSH on %s no longer answers\n' "$GREEN" "$RESET" "$SERVER_IP"
fi

finish
say "$SERVER_NAME is a Server, at root@$(server_host). Next, give it an App:"
say "  deadlift app add <app> --server $SERVER_NAME --repo <owner/name>"
note "Bring it up to date with this checkout any time: deadlift server bootstrap $(server_host)"
note "On Linux, a device with Tailscale 1.93 or earlier needs --accept-routes to reach an App."
if (( ${#SKIPPED[@]} == 0 )); then
  rm -f "$ENV_FILE"
  note "This run's answers are forgotten, so the next run provisions a new Server."
fi
printf '\n'
}

run_wizard "$@"; exit
